export const HTML=`<!doctype html><title>Owned browser gesture fixture</title><style>body{margin:20px;font:16px system-ui}canvas{display:block;border:1px solid;margin-top:20px}textarea{display:block;width:280px;height:90px;margin-top:20px}button{padding:10px}</style><button id="button" onclick="document.querySelector('#status').textContent='Clicked once'">Fixture button</button><button role="menuitem" id="menu" onclick="document.querySelector('#status').textContent='Menu selected'">Fixture menu item</button><p id="status" role="status">No actions</p><textarea aria-label="Synthetic scroll log">${Array.from({length:100},(_,i)=>'Synthetic row '+i).join('\n')}</textarea><canvas width="400" height="180" aria-label="Synthetic draggable canvas">Synthetic draggable canvas</canvas><p role="status" id="canvas-status">Canvas x 40</p><p role="status" id="canvas-clicks">Canvas clicks 0</p><div id="dom-source" role="button" aria-label="Fixture DOM drag source" draggable="true" style="display:inline-block;width:160px;height:70px;border:1px solid;padding:8px" ondragstart="event.dataTransfer.setData('text/plain','fixture-token')">Drag this fixture</div><div id="dom-destination" role="button" aria-label="Fixture DOM drop target" style="display:inline-block;width:160px;height:70px;border:1px solid;margin-left:80px;padding:8px" ondragover="event.preventDefault()" ondrop="event.preventDefault();document.querySelector('#dom-status').textContent=event.dataTransfer.getData('text/plain')==='fixture-token'?'Actual DOM dropped':'Unexpected payload'">Drop here</div><p id="dom-status" role="status">No DOM drop</p><script>const c=document.querySelector('canvas'),g=c.getContext('2d');let x=40,down=false,clicks=0;c.onclick=()=>{document.querySelector('#canvas-clicks').textContent='Canvas clicks '+(++clicks)};function draw(){g.clearRect(0,0,400,180);g.fillStyle='#2365ad';g.fillRect(x,50,50,50)}draw();c.onmousedown=e=>{down=true};c.onmousemove=e=>{if(down){x=e.offsetX;draw();document.querySelector('#canvas-status').textContent='Canvas x '+x}};c.onmouseup=()=>{down=false};</script>`;
